import shipping


def test_fee_free_shipping_range():
    for amount_cents in (0, 9999):
        result = shipping.fee(amount_cents)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 1000

import shipping


def test_fee_threshold_and_above():
    for amount_cents in (10000, 10001):
        result = shipping.fee(amount_cents)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

import pytest
import shipping


def test_non_builtin_int_arguments_raise_type_error():
    for amount_cents in (True, "100"):
        with pytest.raises(TypeError):
            shipping.fee(amount_cents)

